import re

VAGUE = ['fast', 'quickly', 'user-friendly', 'appropriate', 'appropriately', 'easy', 'simple',
         'flexible', 'robust', 'etc', 'some', 'many', 'large', 'minimal', 'as needed']

def vague_terms(text):
    found = set()
    for term in VAGUE:
        if re.search(r'(?<![\w-])' + re.escape(term) + r'(?![\w-])', text, re.IGNORECASE):
            found.add(term)
    return sorted(found)

