function matches(rule, input) {
  return Object.entries(rule.when).every(([k, v]) => v === '-' || input[k] === v);
}
function decide(rules, input) {
  const r = rules.find(rule => matches(rule, input));
  return r ? r.then : 'undefined';
}
function gaps(rules, conditions) {
  const out = [];
  const n = conditions.length;
  for (let mask = 0; mask < 2 ** n; mask++) {
    const input = {};
    conditions.forEach((c, i) => { input[c] = Boolean(mask & (1 << (n - 1 - i))); });
    if (!rules.some(rule => matches(rule, input))) out.push(input);
  }
  return out;
}
